import{loadPlaytestCore,digestBytes,GBA_KEYS}from'./playtest-core.js';
import{playtestStorage}from'./playtest-storage.js';
import{JUMP_SOURCE,jumpToMap}from'./playtest-jump.js';

// WebAudio resamples each buffer at its declared GBA rate to the phone's rate.
class GameAudio{
 constructor(){this.context=null;this.nodes=new Set();this.next=0;this.muted=true;}
 async toggle(){if(!this.context){const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)throw Error('Sound is unavailable in this WebView.');this.context=new Audio({latencyHint:'interactive'});}this.muted=!this.muted;if(this.muted)this.flush();else await this.context.resume();return!this.muted;}
 enqueue(pcm,rate){const c=this.context;if(this.muted||!c||c.state!=='running'||!rate)return;if(this.next>c.currentTime+.25)return;const n=pcm.length/2,b=c.createBuffer(2,n,rate);for(let ch=0;ch<2;ch++){const a=b.getChannelData(ch);for(let i=0;i<n;i++)a[i]=pcm[i*2+ch];}const source=c.createBufferSource();source.buffer=b;source.connect(c.destination);source.onended=()=>{this.nodes.delete(source);source.disconnect();};this.nodes.add(source);const at=Math.max(this.next,c.currentTime+.035);source.start(at);this.next=at+n/rate;}
 flush(){for(const s of this.nodes){try{s.stop();}catch{}}this.nodes.clear();this.next=0;}
 pause(){this.flush();this.context?.suspend().catch(()=>{});}
 resume(){if(!this.muted)this.context?.resume().catch(()=>{});}
 close(){this.flush();this.context?.close().catch(()=>{});}
}

export function createROMPlayer(api,{loadCore=loadPlaytestCore,hash=digestBytes}={}){
 let root=null,core=null,store=null,session=null,frameId=0,saveTimer=0,lastTime=0,accumulator=0,running=false,opening=false,closing=false,saveQueue=Promise.resolve(),listeners=[],audio=null;
 const pointers=new Map(),keyboard=new Map(),$=s=>root?.querySelector(s),esc=api.esc;
 const listen=(target,type,fn,opts)=>{target.addEventListener(type,fn,opts);listeners.push(()=>target.removeEventListener(type,fn,opts));};
 function status(text){if($('#romPlayStatus'))$('#romPlayStatus').textContent=text;}
 function release(){pointers.clear();keyboard.clear();core?.keys();root?.querySelectorAll('[data-gba-key]').forEach(b=>b.classList.remove('held'));}
 const mask=()=>[...pointers.values(),...keyboard.values()].reduce((a,b)=>a|b,0);
 function draw(){if(!core?.loaded)return;const c=$('#romPlayCanvas'),v=core.video();if(!c||!v.width)return;if(c.width!==v.width||c.height!==v.height){c.width=v.width;c.height=v.height;}const ctx=c.getContext('2d'),im=ctx.createImageData(v.width,v.height);im.data.set(v.pixels);ctx.putImageData(im,0,0);}
 function loop(time){if(!running)return;const elapsed=lastTime?Math.min(100,time-lastTime):17;lastTime=time;accumulator=Math.min(accumulator+elapsed,100);const dt=1000/core.fps;let count=0;try{while(accumulator>=dt&&count++<5){core.frame(mask(),(p,r)=>audio.enqueue(p,r));accumulator-=dt;}draw();frameId=requestAnimationFrame(loop);}catch(e){pause(false);api.error(e);status('Playback stopped. Your editor project is still open.');}}
 function resume(){if(!root||closing||document.hidden)return;running=true;lastTime=0;accumulator=0;$('#romPlayPause').textContent='Pause';$('#romPlayMenu').hidden=true;audio.resume();cancelAnimationFrame(frameId);frameId=requestAnimationFrame(loop);}
 function pause(save=true){running=false;cancelAnimationFrame(frameId);frameId=0;release();audio?.pause();if($('#romPlayPause'))$('#romPlayPause').textContent='Resume';if(save)saveNow().catch(api.error);}
 async function saveNow(){if(!core?.loaded||!session)return;const ram=core.saveRAM(),snapshot=core.snapshot(),s=session,at=new Date().toISOString();saveQueue=saveQueue.catch(()=>{}).then(async()=>{if(ram)await store.put({id:s.ramKey,bytes:ram,updatedAt:at});await store.put({id:s.stateKey,bytes:snapshot,ram,updatedAt:at,romHash:s.romHash});});await saveQueue;}
 const download=(bytes,name)=>api.save(new Blob([bytes],{type:'application/octet-stream'}),name);
 async function exportRAM(){pause(false);const ram=core.saveRAM();if(!ram)throw Error('The game has no battery save yet.');await download(ram,'Shattered_Playtest.sav');status('Test save exported. In-game Save records your party and progress.');}
 async function importRAM(file){if(!file)return;pause(false);if(![512,8192,32768,65536,131072].includes(file.size))throw Error('Choose a raw GBA .sav file. Emulator save states are a different format.');const bytes=new Uint8Array(await file.arrayBuffer()),prior=core.saveRAM();if(prior)await store.put({id:'backup:'+session.ramKey,bytes:prior,updatedAt:new Date().toISOString()});core.loadRAM(bytes);await saveNow();draw();status('Imported into the test game. Press Resume, then Continue at the title. Previous test save is backed up.');}
 async function reloadSnapshot(){pause(false);await saveQueue;const saved=await store.get('checkpoint:'+session.stateKey);if(!saved)throw Error('Make a checkpoint for this compiled ROM first.');if(saved.ram)core.loadRAM(saved.ram,{reset:false});core.restore(saved.bytes);draw();status('Checkpoint restored. Press Resume to continue.');}
 function menu(){pause();$('#romPlayMenu').hidden=!$('#romPlayMenu').hidden;}
 async function close(){if(!root||closing)return;closing=true;pause(false);try{await saveNow();}catch(e){closing=false;status(e.message+' Use Saves → Export .sav, or Close without saving.');$('#romPlayMenu').hidden=false;$('#romPlayForceClose').hidden=false;return;}dispose();}
 function dispose(){clearInterval(saveTimer);pause(false);for(const remove of listeners)remove();listeners=[];audio?.close();core?.unload();const old=root;root=null;session=null;old?.close();old?.remove();opening=false;closing=false;api.afterClose?.();}
 async function launch({bytes,sourceId,projectId,title,target=null}){
  if(root||opening)return;opening=true;
  try{const romHash=await hash(bytes);core=await loadCore();core.load(bytes);store=playtestStorage(api.db());session={romHash,ramKey:store.ramKey(projectId,sourceId),stateKey:store.stateKey(romHash),target:sourceId===JUMP_SOURCE?target:null};audio=new GameAudio();
   const saved=await store.get(session.stateKey),ram=saved?.ram||((await store.get(session.ramKey))?.bytes);if(ram)core.loadRAM(ram);if(saved?.bytes)core.restore(saved.bytes);
   root=document.createElement('dialog');root.id='romPlayer';root.className='rom-player';root.setAttribute('aria-label','GBA playtester');root.innerHTML=`<header class="rom-play-header"><strong>${esc(title||'GBA playtest')}</strong><button id="romPlayPause" type="button">Pause</button><button id="romPlayMenuButton" type="button">Saves</button><button id="romPlayClose" type="button" aria-label="Save test session and return to editor">Close</button></header><div class="rom-game-screen"><canvas id="romPlayCanvas" width="240" height="160" aria-label="Live GBA game"></canvas></div><div class="rom-game-controls"><div class="rom-shoulders"><button data-gba-key="l" type="button">L</button><button data-gba-key="r" type="button">R</button></div><div class="rom-pad" aria-label="Direction controls">${[['up','↑'],['left','←'],['right','→'],['down','↓']].map(([k,n])=>`<button type="button" data-gba-key="${k}" aria-label="${k}">${n}</button>`).join('')}</div><div class="rom-ab"><button type="button" data-gba-key="b">B</button><button type="button" data-gba-key="a">A</button></div><div class="rom-system"><button type="button" data-gba-key="select">Select</button><button type="button" data-gba-key="start">Start</button><button id="romPlaySound" type="button">Sound off</button></div></div><p id="romPlayStatus" class="rom-play-status" role="status"></p><section id="romPlayMenu" class="rom-play-menu" aria-label="Test saves and options" hidden><h2>Test game · paused</h2><p>Use the game’s Save command to record party and story progress. Test saves stay separate from your source files.</p><div class="smart-actions"><button id="romPlayExportSave" type="button">Export .sav</button><button id="romPlayImportSave" type="button">Import .sav</button><button id="romPlayExportBackup" type="button">Export previous save</button></div><div class="smart-actions"><button id="romPlayCheckpoint" type="button">Make checkpoint</button><button id="romPlayRestore" type="button">Restore checkpoint</button></div><p class="hint-line">Checkpoints only restore in the exact same compiled ROM. After editing, your battery save carries over and the new ROM starts at its title.</p>${session.target?`<button id="romPlayJump" type="button">Jump to ${esc(target.name)}</button><p class="hint-line">Map jumping is not available in the public build; start from the ROM title screen.</p>`:''}<div class="smart-actions"><button id="romPlayMenuResume" type="button" class="primary">Resume game</button><button id="romPlayReset" type="button">Restart from title</button><button id="romPlayForceClose" type="button" class="danger" hidden>Close without saving</button></div><p><a href="./vendor/mgba/NOTICE.txt" target="_blank" rel="noopener">mGBA · source & licence</a></p><input id="romPlaySaveInput" type="file" accept=".sav,application/octet-stream" hidden></section>`;
   document.body.append(root);root.showModal();draw();status(saved?'Resumed this compiled ROM.':ram?'Test save loaded. Continue from the game’s title.':'Start a new game, or use Saves to import your .sav.');
   const action=fn=>async()=>{try{await fn();}catch(e){status(e.message);api.error(e);}};
   $('#romPlayPause').onclick=()=>running?pause():resume();$('#romPlayMenuButton').onclick=menu;$('#romPlayMenuResume').onclick=resume;$('#romPlayClose').onclick=close;$('#romPlayForceClose').onclick=dispose;
   $('#romPlaySound').onclick=action(async()=>{$('#romPlaySound').textContent=await audio.toggle()?'Sound on':'Sound off';if(!running)audio.pause();});
   $('#romPlayExportSave').onclick=action(exportRAM);$('#romPlayImportSave').onclick=()=>$('#romPlaySaveInput').click();$('#romPlaySaveInput').onchange=action(async()=>{const f=$('#romPlaySaveInput').files[0];await importRAM(f);$('#romPlaySaveInput').value='';});
   $('#romPlayExportBackup').onclick=action(async()=>{const previous=await store.get('backup:'+session.ramKey);if(!previous)throw Error('No replaced test save has been backed up yet.');await download(previous.bytes,'Shattered_Previous_Playtest.sav');});
   $('#romPlayCheckpoint').onclick=action(async()=>{await store.put({id:'checkpoint:'+session.stateKey,bytes:core.snapshot(),ram:core.saveRAM(),updatedAt:new Date().toISOString()});status('Checkpoint saved for this exact ROM.');});$('#romPlayRestore').onclick=action(reloadSnapshot);
   $('#romPlayReset').onclick=action(async()=>{await saveNow();core.reset();draw();status('Restarted from title. Your in-game battery save is retained.');});
   if($('#romPlayJump'))$('#romPlayJump').onclick=action(async()=>{pause(false);const checkpoint=core.snapshot(),ram=core.saveRAM();await store.put({id:'checkpoint:'+session.stateKey,bytes:checkpoint,ram});status('Loading edited map…');await jumpToMap(core,session.target);draw();await saveNow();status('Edited map loaded. Press Resume to play.');});
   root.querySelectorAll('[data-gba-key]').forEach(b=>{listen(b,'pointerdown',e=>{e.preventDefault();if(!running)return;b.setPointerCapture?.(e.pointerId);pointers.set(e.pointerId,GBA_KEYS[b.dataset.gbaKey]);b.classList.add('held');});listen(b,'pointerup',e=>{e.preventDefault();pointers.delete(e.pointerId);b.classList.remove('held');});listen(b,'pointercancel',release);listen(b,'lostpointercapture',e=>{if(pointers.has(e.pointerId))release();});});
   const keymap={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',z:'a',x:'b',Enter:'start',Shift:'select',q:'l',w:'r'};
   listen(document,'keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();menu();return;}const k=keymap[e.key]||keymap[e.key.toLowerCase()];if(k){e.preventDefault();e.stopImmediatePropagation();if(running)keyboard.set(e.code||e.key,GBA_KEYS[k]);}},true);
   listen(document,'keyup',e=>{keyboard.delete(e.code||e.key);},true);listen(window,'blur',()=>pause());listen(document,'visibilitychange',()=>{if(document.hidden)pause();});listen(window,'pagehide',()=>pause());listen(root,'cancel',e=>{e.preventDefault();menu();});
   saveTimer=setInterval(()=>{if(running)saveNow().catch(api.error);},15000);opening=false;resume();
  }catch(e){core?.unload();audio?.close();root?.remove();root=null;session=null;opening=false;throw e;}
 }
 return{launch,close,pause,resume,saveNow,importRAM,get active(){return!!root||opening;},get running(){return running;},get core(){return core;},release};
}
